      batch: { include: { program: true, enrollments: { where: { userId: user.id } } } },
      soals: { select: { id: true, teks: true, pilihanA: true, pilihanB: true, pilihanC: true, pilihanD: true } },
    },
  });

  if (!kuis || kuis.tipe !== "KUIS" || kuis.batch.program.slug !== params.slug) notFound();

  const enrollment = kuis.batch.enrollments.find((e) => e.konsentrasi === "ONLINE");
  if (!enrollment) redirect(`/bootcamp/${params.slug}/overview`);

  // Server-side lock: kuis terkunci jika gate (materi sebelum kuis) belum selesai.
  const list = await getMateriListForEnrollment(enrollment.id);
  const sesi = list.find((s) => s.id === kuis.id);
  if (sesi?.isLocked) redirect(`/bootcamp/${params.slug}/materi`);

  const durasiDetik = kuis.durasi;
  const ambang = kuisAmbang(kuis.urutan);

  return (
    <main className="mx-auto max-w-4xl px-6 py-8">
      <div className="mb-5">
        <p className="text-[13px] text-text-muted">
          <span className="text-online">Online 🎬</span> · {kuis.batch.program.name} ·{" "}
          {kuis.batch.name}
        </p>
        <div className="mt-1 flex flex-wrap items-center gap-3">
          <Badge variant="warning">Sesi {kuis.urutan}</Badge>
          <h1 className="text-[24px] font-extrabold text-navy">{kuis.judul}</h1>
        </div>
      </div>

      {sesi?.status === "SELESAI" ? (
        <HasilNyata enrollmentId={enrollment.id} kuisId={kuis.id} slug={params.slug} />
      ) : (
        <QuizRunner
          kuisId={kuis.id}
          slug={params.slug}
          soal={{
            ambang,
            durasiDetik,
            soal: kuis.soals.map((s) => ({
              id: s.id,
              teks: s.teks,
              pilihan: [s.pilihanA, s.pilihanB, s.pilihanC, s.pilihanD],
            })),
          }}
        />
      )}
    </main>
  );
}

/** Tampil saat kuis sudah dikerjakan (status SELESAI): read-only ringkasan skor + tahap lanjut. */
async function HasilNyata({
  enrollmentId,
  kuisId,
  slug,
}: {
  enrollmentId: string;
  kuisId: string;
  slug: string;
}) {
  const [progress, list] = await Promise.all([
    prisma.progress.findUnique({
      where: { enrollmentId_materiId: { enrollmentId, materiId: kuisId } },
      select: { nilaiKuis: true, completedAt: true },
    }),
    getMateriListForEnrollment(enrollmentId),
  ]);

  const linkTarget = `/${slug ? "bootcamp" : ""}/${slug ? `bootcamp/${slug}` : ""}`;
  const next = list.find((s) => s.urutan === 7);
  const lulus = !!progress?.nilaiKuis && progress.nilaiKuis >= 70;

  return (
    <div className="rounded-card border border-line bg-card p-6 shadow-card">
      <p className="font-display text-[20px] font-bold text-navy">Skor kuis</p>
      <p className="mt-1 font-mono text-[40px] font-extrabold text-gold">
        {progress?.nilaiKuis ?? "—"}
      </p>
      {lulus ? (
        <p className="mt-2 text-[14px] text-online">
          Lulus 🎉{next?.id ? " · Materi 7 kini terbuka." : ""}
        </p>
      ) : (
        <p className="mt-2 text-[14px] text-danger">
          Belum memenuhi nilai minimum. Kamu bisa retake setelah 24 jam.
        </p>
      )}
    </div>
  );
}

