  useEffect(() => {
    const t = setInterval(() => setSisa((s) => (s <= 0 ? 0 : s - 1)), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (sisa === 0 && !hasil) kumpulkan(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sisa]);

  const s = daftarSoal[idx];
