    nilai: number;
    lulus: boolean;
    ambang: number;
    detail: { id: string; dipilih: string; benar: string; bahas: string | null }[];
  } | null>(null);

  // Countdown — kuis otomatis dikumpulkan (submit kosong) saat waktu habis.
  useEffect(() => {
    const t = setInterval(() => setSisa((s) => (s <= 0 ? 0 : s - 1)), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (sisa === 0 && !hasil) kumpulkan(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sisa]);

  const s = daftarSoal[idx];
  const sudahDijawab = (id: string) => jawaban[id] !== undefined;
  const semuaDijawab = daftarSoal.every((q) => sudahDijawab(q.id));

  async function kumpulkan(otomatis = false) {
    if (submitting || (hasil && !otomatis)) return;
    setSubmitting(true);
    try {
      const res = await fetch(`/api/kuis/${kuisId}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ jawaban }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? "Gagal mengumpulkan");
      setHasil(data.hasil);
      router.refresh();
    } catch (e) {
      alert(e instanceof Error ? e.message : "Gagal mengumpulkan kuis");
    } finally {
      setSubmitting(false);
    }
  }

  // ── Layar hasil ──
  if (hasil) {
    return <HasilKuis hasil={hasil} slug={slug} />;
  }

  return (
    <div className="rounded-card border border-line bg-card p-5 shadow-card">
      {/* Header: nama kuis, jumlah soal, countdown */}
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="font-display text-[18px] font-bold text-navy">{soalNama(kuisId)}</p>
          <p className="text-[13px] text-text-secondary">
            {total} soal · nilai minimum lulus {ambang}
          </p>
        </div>
        <div
          className={`inline-flex items-center gap-2 rounded-full px-3 py-1.5 font-mono text-[14px] font-bold ${
            sisa <= 60 ? "bg-danger-bg text-danger" : "bg-[#F1EFE8] text-navy"
          }`}
          role="timer"
          aria-label="Sisa waktu"
        >
          <Timer className="h-4 w-4" aria-hidden />
          {formatClock(sisa)}
        </div>
      </div>

      {/* Navigasi soal: pill angka */}
      <nav aria-label="Navigasi soal" className="mb-5 flex flex-wrap gap-2">
        {daftarSoal.map((q, i) => (
          <button
            key={q.id}
            onClick={() => setIdx(i)}
            aria-current={i === idx}
            className={`h-9 w-9 rounded-full text-[13px] font-bold transition-colors ${
              i === idx
                ? "bg-gold text-navy ring-2 ring-gold"
                : sudahDijawab(q.id)
                  ? "bg-navy text-gold"
                  : "bg-[#F1EFE8] text-text-secondary hover:bg-line"
            }`}
          >
            {i + 1}
          </button>
        ))}
      </nav>

      {/* Satu soal per layar */}
      <div className="min-h-[220px]">
        <p className="mb-3 text-[13px] font-semibold text-text-muted">Soal {idx + 1} dari {total}</p>
        <p className="mb-5 text-[17px] font-semibold leading-relaxed text-navy">{s.teks}</p>
        <div className="space-y-2.5">
          {s.pilihan.map((opt, i) => {
            const kunci = abjad[i];
            const dipilih = jawaban[s.id] === kunci;
            return (
              <label
                key={kunci}
                className={`flex cursor-pointer items-center gap-3 rounded-btn border-[1.5px] px-4 py-3 transition-colors ${
                  dipilih ? "border-gold bg-gold-light" : "border-line bg-white hover:border-gold/60"
                }`}
              >
                <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-navy font-mono text-[13px] font-bold text-gold">
                  {kunci}
                </span>
                <span className="text-[14px] text-navy">{opt}</span>
                <input
                  type="radio"
                  name={s.id}
                  value={kunci}
                  checked={dipilih}
                  onChange={() => setJawaban((j) => ({ ...j, [s.id]: kunci }))}
                  className="sr-only"
                />
              </label>
            );
          })}
        </div>
      </div>

      {/* Tombol navigasi */}
      <div className="mt-6 flex items-center justify-between border-t border-line pt-4">
        <Button variant="ghost" onClick={() => setIdx((i) => Math.max(0, i - 1))} disabled={idx === 0}>
