        </Button>
        <div className="flex items-center gap-3">
          <span className="text-[13px] text-text-muted">
            {Object.keys(jawaban).length}/{total} dijawab
          </span>
          {idx < total - 1 ? (
            <Button variant="primary" onClick={() => setIdx((i) => Math.min(total - 1, i + 1))}>
              Berikutnya <ArrowRight className="h-4 w-4" aria-hidden />
            </Button>
          ) : (
            <Button
              variant="primary"
              onClick={() => kumpulkan()}
              disabled={!semuaDijawab || submitting}
              title={semuaDijawab ? "Kumpulkan kuis" : "Semua soal harus dijawab dulu"}
            >
              {submitting ? (
                <Loader2 className="h-4 w-4 animate-spin" aria-hidden />
              ) : (
                <Send className="h-4 w-4" aria-hidden />
              )}
              Kumpulkan
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

